  "inlineSchema": "// ============================================\n// Prisma Schema - Clothing Factory Management\n// ============================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ===== USERS & AUTH =====\nenum Role {\n  admin // كل الصلاحيات + إدارة المستخدمين\n  manager // كل العمليات بدون إدارة المستخدمين\n  viewer // قراءة فقط\n}\n\nmodel User {\n  id         Int       @id @default(autoincrement())\n  username   String    @unique\n  password   String\n  full_name  String\n  role       Role      @default(viewer)\n  is_active  Boolean   @default(true)\n  last_login DateTime?\n  created_at DateTime  @default(now())\n  updated_at DateTime  @updatedAt\n\n  @@map(\"users\")\n}\n\n// ===== SALES =====\nmodel Sale {\n  id                 Int      @id @default(autoincrement())\n  order_number       String\n  row_number         Int      @default(0)\n  marketer           String   @default(\"\")\n  client             String\n  model1_code        String   @default(\"\")\n  model1_qty         Int      @default(0)\n  model1_color       String   @default(\"\")\n  model2_code        String   @default(\"\")\n  model2_qty         Int      @default(0)\n  model2_color       String   @default(\"\")\n  model3_code        String   @default(\"\")\n  model3_qty         Int      @default(0)\n  model3_color       String   @default(\"\")\n  model4_code        String   @default(\"\")\n  model4_qty         Int      @default(0)\n  model4_color       String   @default(\"\")\n  model5_code        String   @default(\"\")\n  model5_qty         Int      @default(0)\n  model5_color       String   @default(\"\")\n  invoice_value      Float    @default(0)\n  deposit_paid       Float    @default(0)\n  deposit_receiver   String   @default(\"\")\n  remaining          Float    @default(0)\n  shipping_number    String   @default(\"\")\n  order_status       String   @default(\"لم يتم الصرف\")\n  delivery_method    String   @default(\"\")\n  mobile             String   @default(\"\")\n  warehouse          String   @default(\"\")\n  shipping_collected Float    @default(0)\n  created_at         DateTime @default(now())\n\n  @@map(\"sales\")\n}\n\n// ===== EXPENSES & REVENUES =====\nmodel ExpenseRevenue {\n  id             Int      @id @default(autoincrement())\n  date           String\n  operation_type String\n  statement      String\n  hatem_in       Float    @default(0)\n  hatem_out      Float    @default(0)\n  mido_in        Float    @default(0)\n  mido_out       Float    @default(0)\n  created_at     DateTime @default(now())\n\n  @@map(\"expenses_revenues\")\n}\n\n// ===== READY STOCK =====\nmodel ReadyStock {\n  id              Int    @id @default(autoincrement())\n  model_code      String\n  product_name    String\n  color           String @default(\"\")\n  opening_balance Int    @default(0)\n  cost_per_piece  Float  @default(0)\n  location        String @default(\"\")\n  mido_stock      Int    @default(0)\n  hatem_stock     Int    @default(0)\n\n  @@map(\"ready_stock\")\n}\n\n// ===== FABRIC WAREHOUSE =====\nmodel FabricWarehouse {\n  id            Int      @id @default(autoincrement())\n  date          String\n  material_type String\n  color         String   @default(\"\")\n  qty_in        Float    @default(0)\n  cost_per_kg   Float    @default(0)\n  created_at    DateTime @default(now())\n\n  @@map(\"fabric_warehouse\")\n}\n\n// ===== ACCESSORIES WAREHOUSE =====\nmodel AccessoriesWarehouse {\n  id           Int      @id @default(autoincrement())\n  date         String\n  item_name    String\n  qty_in       Float    @default(0)\n  qty_consumed Float    @default(0)\n  cost         Float    @default(0)\n  created_at   DateTime @default(now())\n\n  @@map(\"accessories_warehouse\")\n}\n\n// ===== CUTTING ORDERS =====\nmodel CuttingOrder {\n  id              Int      @id @default(autoincrement())\n  date            String\n  cut_number      Int\n  cut_description String   @default(\"\")\n  material_type   String\n  layers_count    Int      @default(0)\n  spread_length_m Float    @default(0)\n  total_pieces    Int      @default(0)\n  color           String   @default(\"\")\n  kg_consumed     Float    @default(0)\n  notes           String   @default(\"\")\n  created_at      DateTime @default(now())\n\n  @@map(\"cutting_orders\")\n}\n\n// ===== MODEL PRODUCTION =====\nmodel ModelProduction {\n  id                   Int      @id @default(autoincrement())\n  date                 String\n  cut_number           Int\n  model_code           String\n  qty_from_cutting     Int      @default(0)\n  model_description    String   @default(\"\")\n  color                String   @default(\"\")\n  sizes                String   @default(\"\")\n  status               String   @default(\"قيد التشغيل\")\n  wastage              Int      @default(0)\n  qty_received         Int      @default(0)\n  warehouse_entry_date String   @default(\"\")\n  created_at           DateTime @default(now())\n\n  @@map(\"model_productions\")\n}\n\n// ===== DEBTS =====\nmodel Debt {\n  id           Int      @id @default(autoincrement())\n  date         String\n  name         String\n  total_amount Float    @default(0)\n  amount_paid  Float    @default(0)\n  remaining    Float    @default(0)\n  created_at   DateTime @default(now())\n\n  @@map(\"debts\")\n}\n\n// ===== CLIENT ACCOUNTS =====\nmodel ClientAccount {\n  id           Int      @id @default(autoincrement())\n  date         String\n  client_name  String\n  model_name   String   @default(\"\")\n  quantity     Int      @default(0)\n  total_amount Float    @default(0)\n  amount_paid  Float    @default(0)\n  remaining    Float    @default(0)\n  notes        String   @default(\"\")\n  created_at   DateTime @default(now())\n\n  @@map(\"client_accounts\")\n}\n\n// ===== RETURNS =====\nmodel ReturnItem {\n  id            Int      @id @default(autoincrement())\n  date          String\n  order_number  String   @default(\"\")\n  client_name   String\n  returned_by   String   @default(\"\")\n  paid_by       String   @default(\"\")\n  model_code    String   @default(\"\")\n  model_qty     Int      @default(0)\n  model_color   String   @default(\"\")\n  refund_amount Float    @default(0)\n  notes         String   @default(\"\")\n  created_at    DateTime @default(now())\n\n  @@map(\"return_items\")\n}\n\n// ===== PAYMENT LOGS =====\nmodel PaymentLog {\n  id          Int      @id @default(autoincrement())\n  date        String\n  type        String\n  amount      Float    @default(0)\n  receiver    String   @default(\"\")\n  description String   @default(\"\")\n  created_at  DateTime @default(now())\n\n  @@map(\"payment_logs\")\n}\n\n// ===== MARKETERS (moved from localStorage to DB) =====\nmodel Marketer {\n  id         Int      @id @default(autoincrement())\n  name       String   @unique\n  created_at DateTime @default(now())\n\n  @@map(\"marketers\")\n}\n",
